}

package com.viraj.dmabackend.menu.bootstrap;

import com.viraj.dmabackend.menu.entity.Menu;
import com.viraj.dmabackend.menu.repository.MenuRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.boot.CommandLineRunner;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@Order(4)
public class MenuBootstrap implements CommandLineRunner {

    private final MenuRepository menuRepository;

    @Override
    public void run(String... args) {

        if (menuRepository.count() > 0) {
            return;
        }

        // ==========================================
        // 1. Root: Dashboard
        // ==========================================
        createMenu(
                "Dashboard",
                "/dashboard",
                "layout-dashboard",
                null,
                1,
                null);


        // ==========================================
        // 2. Root: Leads CRM & Submenus
        // ==========================================
        Menu leadsRoot = createMenu(
                "Leads CRM",
                "/leads",
                "users",
                null,
                2,
                "lead:read");
        createMenu(
                "All Leads",
                "/leads/all",
                "list",
                leadsRoot.getId(),
                1,
                "lead:read");
        createMenu(
                "Create Lead",
                "/leads/new",
                "user-plus",
                leadsRoot.getId(),
                2,
                "lead:create");


        // ==========================================
        // 3. Root: Client Management & Submenus
        // ==========================================
        Menu clientsRoot = createMenu(
                "Client Management",
                "/clients",
                "briefcase",
                null,
                3,
                "client:read");
        createMenu(
                "All Clients",
                "/clients/all",
                "building",
                clientsRoot.getId(),
                1,
                "client:read");
        createMenu(
                "Add Client",
                "/clients/new",
                "plus-circle",
                clientsRoot.getId(),
                2,
                "client:create");


        // ==========================================
        // 4. Root: Project Management & Submenus
        // ==========================================
        Menu projectsRoot = createMenu(
                "Project Management",
                "/projects",
                "folder-kanban",
                null,
                4,
                "project:read");
        createMenu(
                "All Projects",
                "/projects/all",
                "layers",
                projectsRoot.getId(),
                1,
                "project:read");
        createMenu(
                "New Project",
                "/projects/new",
                "folder-plus",
                projectsRoot.getId(),
                2,
                "project:create");


        // ==========================================
        // 5. Root: Invoice & Billing & Submenus
        // ==========================================
        Menu invoicesRoot = createMenu(
                "Invoice & Billing",
                "/invoices",
                "receipt",
                null,
                5,
                "invoice:read");
        createMenu(
                "All Invoices",
                "/invoices/all",
                "file-text",
                invoicesRoot.getId(),
                1,
                "invoice:read");
        createMenu(
                "Create Invoice",
                "/invoices/new",
                "file-plus",
                invoicesRoot.getId(),
                2,
                "invoice:create");


        // ==========================================
        // 6. Root: System Administration & Submenus
        // ==========================================
        Menu settingsRoot = createMenu(
                "System Administration",
                "/settings",
                "settings",
                null,
                6,
                "role:read");
        createMenu(
                "User Accounts",
                "/settings/users",
                "user-cog",
                settingsRoot.getId(),
                1,
                "user:read");
        createMenu(
                "Roles & Permissions",
                "/settings/roles",
                "shield",
                settingsRoot.getId(),
                2,
                "role:read");
    }

    private Menu createMenu(String title, String path, String icon, String parentId, Integer orderIndex, String requiredPermission) {
        Menu menu = Menu.builder()
                .title(title)
                .path(path)
                .icon(icon)
                .parentId(parentId)
                .orderIndex(orderIndex)
                .requiredPermission(requiredPermission)
                .active(true)
                .build();

        return menuRepository.save(menu);
    }
}

package com.viraj.dmabackend.menu.mapper;

import com.viraj.dmabackend.menu.dto.MenuResponse;
import com.viraj.dmabackend.menu.dto.MenuTreeResponse;
import com.viraj.dmabackend.menu.entity.Menu;
import org.springframework.stereotype.Component;

@Component
public class MenuMapper {

    public MenuResponse toMenuResponse(Menu menu) {

        return MenuResponse.builder()
                .id(menu.getId())
                .title(menu.getTitle())
                .path(menu.getPath())
                .icon(menu.getIcon())
                .parentId(menu.getParentId())
                .orderIndex(menu.getOrderIndex())
                .requiredPermission(menu.getRequiredPermission())
                .active(menu.getActive())
                .build();
    }

    public MenuTreeResponse toMenuTreeResponse(Menu menu) {

        return MenuTreeResponse.builder()
                .id(menu.getId())
                .title(menu.getTitle())
                .path(menu.getPath())
                .icon(menu.getIcon())
                .orderIndex(menu.getOrderIndex())
                .requiredPermission(menu.getRequiredPermission())
                .build();
    }
}

package com.viraj.dmabackend.menu.validator;

import com.viraj.dmabackend.menu.exception.DuplicateMenuPathException;
import com.viraj.dmabackend.menu.exception.DuplicateMenuTitleException;
import com.viraj.dmabackend.menu.exception.InvalidMenuPathException;
import com.viraj.dmabackend.menu.exception.ParentMenuNotFoundException;
import com.viraj.dmabackend.menu.exception.SelfParentMenuException;
import com.viraj.dmabackend.menu.repository.MenuRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
public class MenuValidator {

    private final MenuRepository menuRepository;

    public void validateDuplicateTitle(String title) {

        if (menuRepository.findByTitle(title).isPresent()) {
            throw new DuplicateMenuTitleException(title);
        }
    }

    public void validateDuplicatePath(String path) {

        if (menuRepository.findByPath(path).isPresent()) {
            throw new DuplicateMenuPathException(path);
        }
    }

    public void validateParentExists(String parentId) {

        if (parentId == null || parentId.isBlank()) {
            return;
        }
        menuRepository.findById(parentId)
                .orElseThrow(() -> new ParentMenuNotFoundException(parentId));
    }

    public void validateParentRelationship(String menuId, String parentId) {

        if (menuId == null || parentId == null) {
            return;
        }
        if (menuId.equals(parentId)) {
            throw new SelfParentMenuException();
        }
    }

    public void validatePath(String path) {

        if(!path.startsWith("/")){
            throw new InvalidMenuPathException(path);
        }
    }

    public void validateDuplicateTitleForUpdate(String title, String menuId) {

        if (menuRepository.existsByTitleAndIdNot(title, menuId)) {
            throw new DuplicateMenuTitleException(title);
        }
    }

    public void validateDuplicatePathForUpdate(String path, String menuId) {

        if (menuRepository.existsByPathAndIdNot(path, menuId)) {
            throw new DuplicateMenuPathException(path);
        }
    }
}

package com.viraj.dmabackend.client.controller;

import com.viraj.dmabackend.client.enums.ClientStatus;
import com.viraj.dmabackend.client.dto.ClientResponse;
import com.viraj.dmabackend.client.dto.CreateClientRequest;
import com.viraj.dmabackend.client.dto.UpdateClientRequest;
import com.viraj.dmabackend.client.service.ClientService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.security.SecurityRequirement;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.http.HttpStatus;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@Tag(name = "6. Client Management")
@RestController
@RequestMapping("/api/clients")
@RequiredArgsConstructor
@SecurityRequirement(name = "Bearer Authentication")
public class ClientController {

    private final ClientService clientService;

    @PreAuthorize("hasAuthority('client:create')")
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    @Operation(summary = "Create Client")
    public ClientResponse createClient(
            @Valid @RequestBody CreateClientRequest request) {

        return clientService.createClient(request);
    }

    @PreAuthorize("hasAuthority('client:read')")
    @GetMapping
    @ResponseStatus(HttpStatus.OK)
    @Operation(summary = "Get All Clients")
    public Page<ClientResponse> getAllClients(Pageable pageable) {

        return clientService.getAllClients(pageable);
    }

    @PreAuthorize("hasAuthority('client:read')")
    @GetMapping("/{clientId}")
    @ResponseStatus(HttpStatus.OK)
    @Operation(summary = "Get Client By Id")
    public ClientResponse getClientById(
            @PathVariable String clientId) {

        return clientService.getClientById(clientId);
    }

    @PreAuthorize("hasAuthority('client:read')")
    @GetMapping("/search")
    @ResponseStatus(HttpStatus.OK)
    @Operation(summary = "Search Clients")
    public Page<ClientResponse> searchClients(
            @RequestParam String keyword,
            Pageable pageable) {

        return clientService.searchClients(keyword, pageable);
    }

    @PreAuthorize("hasAuthority('client:read')")
    @GetMapping("/status")
    @ResponseStatus(HttpStatus.OK)
    @Operation(summary = "Filter Clients By Status")
    public Page<ClientResponse> filterClientsByStatus(
            @RequestParam ClientStatus status,
            Pageable pageable) {

        return clientService.filterClientsByStatus(status, pageable);
    }

    @PreAuthorize("hasAuthority('client:update')")
    @PutMapping("/{clientId}")
    @ResponseStatus(HttpStatus.OK)
    @Operation(summary = "Update Client")
    public ClientResponse updateClient(
            @PathVariable String clientId,
            @Valid @RequestBody UpdateClientRequest request) {

        return clientService.updateClient(clientId, request);
    }

    @PreAuthorize("hasAuthority('client:delete')")
    @DeleteMapping("/{clientId}")
